process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0'; //enable self-signed certificates

const fs = require('fs');
const path = require('path');
const Promise = require('bluebird');
const ws = require('ws');
const fetchBundle = require('./fetchBundle');

init();

function init() {
    const argv = normalizeArgv();

    if(argv['bts-username'] && argv['bts-password'] && argv['bts-host'] && argv['bts-port'] && (argv['cli-port'] || argv['data'])) {
        const loginData = {
            userName: argv['bts-username'],
            token: argv['bts-password'],
            host: argv['bts-host'],
            port: argv['bts-port'],
            updateInterval: (argv['interval']) ? toNumber(argv['interval']) : 5000,
            isSecure: argv['secure'] ? toBoolean(argv['secure']) : false,
            authMethod: {
                id: 2,
                name: 'PLAIN_TEXT'
            }

        };
        const localStorage = {};
        const sessionStorage = {currentUser: loginData};
        const uri = `${loginData.isSecure ? 'https' : 'http'}://${loginData.host}:${loginData.port}/bundle.js`;
        const bundlesDir = argv['bundles-dir'] || path.join(path.resolve(__dirname), 'bundles');

        if (!argv['bundle-path'] && !fs.existsSync(bundlesDir)) {
            fs.mkdirSync(bundlesDir);
        }

        const fetchBundlePromise = argv['bundle-path'] ? Promise.resolve(argv['bundle-path']) : fetchBundle(uri, bundlesDir, 'js');

        fetchBundlePromise
            .then((bundlePath) => {
                global.navigator = {userAgent: 'CLI'};
                global.WebSocket = ws; //W3C Websocket polyfill
                global.window = global;
                require(bundlePath);
                if(argv['debug'] || !argv['cli-port']) {
                    global.log4javascript.getRootLogger().removeAllAppenders(); //remove existing loggers
                    if(argv['debug']) {
                        const debugFile = argv['debug'];
                        const logStream = fs.createWriteStream(debugFile, {'flags': 'a'});
                        const fileAppender = getFileAppender(logStream);
                        global.log4javascript.getRootLogger().addAppender(fileAppender);
                    }
                }
                global.adminCore.adminApi.initCli({localStorage: localStorage, sessionStorage: sessionStorage});
                adminApiHandler();
            })
            .catch((err) => {
                console.error(err);
                process.exit(1);
            });
    }
    else {
        const help = [
            'Usage: admin-cli [options...]',
            'Options:',
            '--bts-username             BTS username',
            '--bts-password             BTS password',
            '--bts-host                 BTS host',
            '--bts-port                 BTS port',
            '--cli-host=localhost       CLI socket server port',
            '--cli-port                 CLI socket server port',
            '--interval=5000            Specifies how fast updates should arriving in milliseconds',
            '--secure=false             Secure connection',
            '--data                     JSON format request',
            '--file-input               File to be included into the request message',
            '--file-token               Unique string token to be replaced by a --file-input content within the request message e.g {... "scf":"CUSTOM_FILE_TOKEN"}',
            '--file-output              Payload file extracted from the response message',
            '--debug=STDOUT             Log file',
            '--bundle-path              Explicit bundle path',
            '--bundles-dir=src/bundles  Bundles directory',
            '',
            'Example: admin-cli --bts-username=\'user\' --bts-password=\'123\' --bts-host=\'127.0.0.1\' --bts-port=\'8000\' --data=\'{"key":"value"}\''
        ];
        console.log(help.join('\n'));
        return;
    }

    function adminApiHandler() {
        const adminApi = global.adminCore.adminApi.adminApi;
        var fakeSocket;

        if(argv['cli-port']) {
            const cliHost = argv['cli-host'] || 'localhost';
            const cliPort = toNumber(argv['cli-port']);

            const wss = new ws.Server({host: cliHost, port: cliPort});
            fakeSocket = createFakeSocket(broadcast);

            wss.on('connection', (ws) => {
                ws.on('message', (request) => {
                    adminApi.handle(request, fakeSocket);
                });
            });

            function broadcast(data) {
                wss.clients.forEach((client) => {
                    client.send(data);
                });
            };

            console.log(`CLI server is listening on ${cliHost}:${cliPort}`);
        }
        else {
            if(argv['file-input'] && argv['file-token']) {
                const byteArrayStr = (new Uint8Array(fs.readFileSync(argv['file-input']))).toString();
                argv['data'] = argv['data'].replace(new RegExp(`[",']?${argv['file-token']}[",']?`), `[${byteArrayStr}]`);
            }

            fakeSocket = createFakeSocket((response) => {
                const json = JSON.parse(response);
                if(json.requestStatus === 'completed' && argv['file-output'] && isBase64(json.payload)) {
                    fs.writeFileSync(argv['file-output'], json.payload, {encoding: 'base64'});
                    json.payload = '';
                    response = JSON.stringify(json);
                }
                console.log(response);
                if(json.requestStatus === 'completed' || json.requestStatus === 'failed') {
                    process.exit(0);
                }
            });
            const request = argv['data'];
            adminApi.handle(request, fakeSocket);
        }
    }
}

function normalizeArgv() {
    const argv = {};
    process.argv.slice(2).forEach((arg) => {
        const splitted = arg.split('=');
        if(splitted.length === 2) {
            argv[splitted[0].replace(/^[-]*/, '')] = splitted[1];
        }
    });
    return argv;
}

function getFileAppender(logStream) {
    function FileAppender(logStream) {
        this.logStream = logStream;
        this.setLayout(new global.log4javascript.PatternLayout("%d{HH:mm:ss} %-5p %c - %m%n"));
    }
    FileAppender.prototype = new global.log4javascript.Appender();
    FileAppender.prototype.append = function (loggingEvent) {
        const formattedMessage = this.getLayout().format(loggingEvent).toString();
        this.logStream.write(formattedMessage);
    }

    return new FileAppender(logStream);
}

function createFakeSocket(callback) {
    return {send: callback};
}

function toNumber(str) {
    const number = Number(str);
    if(isNaN(number)) {
        throw new Error(`Parse error: '${str}' is not a number.`)
    }
    return number;
}

function toBoolean(str) {
    if(str !== 'true' && str !== 'false') {
        throw new Error(`Parse error: '${str}' is not a boolean.`)
    }
    return str === 'true';
}

function isBase64(str) {
    const base64regex = /^([0-9a-zA-Z+/]{4})*(([0-9a-zA-Z+/]{2}==)|([0-9a-zA-Z+/]{3}=))?$/;
    return base64regex.test(str);
}
